-- SIM40 demo catalogue (S-Bahn Berlin Stromschiene tender): 4 suppliers, 73 priced products, 2 subcontractors,
-- 335 activities with own prices and subcontractor offer prices. All names and prices are fictional estimates.
-- Run once on an empty catalogue, after migrations up to 023:  psql -d <db> -v ON_ERROR_STOP=1 -f db/seeds/sim40_catalogue.sql

SET client_encoding = 'UTF8';
BEGIN;
CREATE TEMP TABLE seed (supplier text, cat text, sku text, name text, description text, unit text, price numeric) ON COMMIT DROP;
SELECT s.id, c.id, v.sku, v.name, v.description, v.unit
FROM seed v JOIN supplier s ON s.name = v.supplier JOIN product_category c ON c.name = v.cat;
SELECT p.id, DATE '2026-11-01', 'EUR', v.price, 'supplier_quote'
FROM seed v JOIN supplier s ON s.name = v.supplier JOIN product p ON p.supplier_id = s.id AND p.supplier_sku = v.sku;
SELECT DISTINCT s.id, c.id FROM seed v JOIN supplier s ON s.name = v.supplier JOIN product_category c ON c.name = v.cat;
COMMIT;

