INSERT INTO activity (code, kind, name, description, unit_code, category) VALUES
('01.01.0010', 'activity', 'Ausführungsplanung Gleichstrom-Fahrleitungsanlage und Rückleitungsanlage erstellen', 'Erstellung einer genehmigungsfähigen Ausführungsplanung für die Gleichstrom-Fahrleitungsanlage und Rückleitungsanlage im Endzustand und für alle notwendigen Bauzustände. Ausführungsplanung in Anlehnung an das Leistungsbild der HOAI, Objektplanung für technische Ausrüstungen, LPH 5 sowie den Planungskatalogen und Planungsvorgaben des Betreiber zu erstellen. Anzahl der zu liefernden Ausführungsunterlagen: ... fach zur fachtechnischen Prüfung ... fach zur EBA-Prüfung ... fach gleichgestellt Prüfbemerkungen sind mit den Gleichstellungen einzuarbeiten, Genehmigungsvermerke sind zu übertragen.', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0020', 'activity', 'Ausführungsplanung Gleichstrom-Fahrleitungsanlage und Rückleitungsanlage prüfen', NULL, 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0030', 'activity', 'Ausführungsplanung Kabeltiefbau erstellen', NULL, 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0040', 'activity', 'Ausführungsplanung Kabeltiefbau prüfen', NULL, 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0060', 'activity', 'Schematischen Rückleiterplan bearbeiten / erstellen', 'Grundlagenplan wird beigestellt. Änderung aufgrund von Baumaßnahmen sind im Plan digital einzuarbeiten. Übergabe der Pläne 25-fach auf Papier und 1-fach auf Datenträger. Position gilt für alle geänderten Bauzustände unabhängig von deren Länge und für den Endzustand. Abgerechnet wird nach Stück bearbeiteter Grundlagenplan.', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0070', 'activity', 'Lagepläne handrevidiert erstellen', 'Handrevision nach der Baudurchführung ergänzen. Grundlage sind die freigegebenen Lagepläne aus der Ausführungsplanung. Übereinstimmungsvermerk zwischen handrevidiertem Plan und Baudurchführung mit Unterschrift im Schriftfeld bestätigen. Pläne 3-fach farbig als Papierexemplar übergeben', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0100', 'activity', 'Stromschienenaufmaß erstellen', 'Metergenaues Aufmessen der Spitzen, Dilatationen, Festpunkte und Kabelanschlusspunkte, Darstellen der Angaben in Tabellenform. Aufmaß 2-fach als Papierexemplar und 1-fach auf Datenträger übergeben', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0110', 'activity', 'Standort Signalschild einmessen', NULL, 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0130', 'activity', 'Entsorgungskonzept erstellen', 'Der Auftragnehmer hat auf der Basis der Ausschreibung und unter Berücksichtigung der ggf. vom Auftraggeber übergebenen Planunterlagen und Gutachten sowie der naturräumlichen, flächenmäßigen und technologischen Gegebenheiten des Bauvorhabens ein verbindliches vorhabenbezogenes Entsorgungskonzept zu erstellen. Der Entwurf des Entsorgungskonzeptes ist spätestens 2 Wochen nach Zuschlagserteilung, die erste Vollversion spätestens 5 Wochen vor Baubeginn beim AG zur Bestätigung vorzulegen. Der Bauüberwachung ist eine Kopie des Entsorgungskonzeptes als Arbeitsmittel zu übergeben. Das Vorliegen eines bestätigten Entsorgungskonzeptes ist Voraussetzung für jegliche Wiedereinbau- oder Entsorgungsmaßnahmen. Das Entsorgungskonzept ist vom Auftragnehmer unter Berücksichtigung des Bauablaufes kontinuierlich fortzuschreiben und in seiner jeweiligen aktuellen Fassung beim Auftraggeber zur Bestätigung vorzulegen. Den Erlös von der Entsorgung erhält der Auftraggeber.', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0150', 'activity', 'Zuarbeit zum Sicherheits- und Gesundheitsschutzplan', '(SiGe-Plan) gemäß Baustellenverordnung erstellen und fortschreiben.', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.01.0160', 'activity', 'Gleislageüberwachung Schutzrohrquerung', 'Messtechnische Überwachung der Gleislage während des Rohrvortriebs einschließlich Kontrolle bis zum Abklingen der Setzungen gemäß Ril 836.0700. Einschließlich Null-Messung des Ausgangszustandes vor Beginn der Baumaßnahme. Bei den Vermessungsarbeiten sind ggf. vorhandene Landesfestpunkte, Grenzmarken usw. zu sichern. Fehlende oder zerstörte Punkte sind durch den AN neu zu erstellen. Abgerechnet wird nach Stück Rohrquerung.', 'St', 'Pläne, Konzepte, Gutachtung und Beweissicherung'),
('01.02.0010', 'activity', 'Genehmigung zur Benutzung öffentlicher und privater Straßen und Wege zum Materialan- und abtransport von und zur Baustelleneinrichtungsfläche', 'einholen Beantragung bei der zuständigen Landesbehörde.', 'St', 'Genehmigungen und Bescheinigungen'),
('01.02.0020', 'activity', 'Genehmigung zur Nutzung von öffentlichen und privaten Flächen für die Baustelleneinrichtungsfläche', 'einholen Beantragung bei der zuständigen Landesbehörde.', 'St', 'Genehmigungen und Bescheinigungen'),
('01.02.0030', 'activity', 'Genehmigung und Schachtscheine für Arbeiten in der Nähe von Ver- und Entsorgungsleitungen', 'einholen Beantragung bei der zuständigen Landesbehörde.', 'St', 'Genehmigungen und Bescheinigungen'),
('01.02.0090', 'activity', 'Genehmigung für die Bauausführung am Wochenende', 'einholen Beantragung bei der zuständigen Landesbehörde.', 'St', 'Genehmigungen und Bescheinigungen'),
('01.03.0010', 'activity', 'Herstellung Revisions- und Bestandsunterlagen DB Netz AG', 'für S-Bahnstromanlagen entsprechend dem "Handbuch für die Erstellung von Planungen und Bestandsdokumentationen (Fachpläne) für Anlagen der S-Bahnstromversorgung Berlin" in der aktuellsten Fassung herstellen. Darstellung der neuen und geänderten Anlagen auf digitalisierten Plänen. Die Bestandsunterlagen sind auf der Basis von Microstation (dgn-Format) zuzüglich CAD Ergänzungsinformationen im dwg und dxf-Format (einschl. der dazugehörigen Plotdateien *.plt) anzufertigen. Das Herstellen der Bestandsunterlagen ist mit dem Anlagenverantwortlichen abzustimmen. Bestandsunterlagen für alle von der Baumaßnahme betroffenen Anlagenteile der S-Bahnstromversorgung.', 'St', 'Revisionsdokumente'),
('01.03.0100', 'activity', 'Datenaufnahme der geänderten Anlagenstruktur gemäß SAP-Vorgaben', 'Für die Datenaufnahme werden vom AG vorgegebene Aufnahmeblätter dem AN übergeben. Dem AG sind die ausgefüllten Aufnahmeblätter im Entwurfsstatus mindestens 30 Werktage vor der Inbetriebsetzung der Anlage vom AN zu übergeben, sodass der Bezirksleiter eine Vorprüfung der sachlichen Richtigkeit durchführen kann. Nach der Inbetriebsetzung der Anlage sind die ggf. angepassten Aufnahmeblätter im Finalstatus innerhalb von 5 Werktagen dem AG zu übergeben. Erst mit der Unterschrift des Bezirksleiter nach Prüfung der sachlichen Richtigkeit gilt die Position als abgeschlossen und abrechnungsfähig.', 'psch', 'Revisionsdokumente'),
('02.01.2020', 'activity', 'Kabel im Kabelkagnal verlegen, Kabeldurchmesser ab 20 mm bis 40 mm', 'Kabel im Kabelkanal verlegen, Kabeldurchmesser ab 20 mm bis 40 mm Anbringung der Kabelkennzeichnung und Kabelbefestigung eingeschlossen. Kabelkanal auf- und zudeckeln wird gesondert vergütet. Einbau von Kabelkanälen wird gesondert vergütet. Verlegung muss verwindungsfrei zu anderen Kabeln erfolgen. Abrechnungslänge gilt von Endverschluss bis Endverschluss.', 'm', 'Kabel, Leitungen und Zubehör'),
('02.01.2190', 'activity', 'Gleisanschlussverbinder 120 mm², einschienig, nah, konvektioniert an Schwelle / Fahrschiene verlegen', 'Verlegung muss verwindungsfrei erfolgen. Position beinhaltet 4 Gleisanschlussverbinder mit einer Länge von jeweils ca. 3,50 m.', 'm', 'Kabel, Leitungen und Zubehör'),
('02.01.2280', 'activity', 'Ankerschiene und Kabelschellen für Parallelen Rückleiter einbauen', 'Zur Sicherung des Parallelen Rückleiters im Betonkabelkanal in unregelmäßigen Abständen alle 3 bis 5 m einbauen.', 'St', 'Kabel, Leitungen und Zubehör'),
('02.01.4010', 'activity', 'Kabel aus Kabelkanal ausbauen, Kabeldurchmesser bis 20 mm', 'Lagerung im Kabelring oder auf Kabeltrommel. Kabelenden mit Schrumpfkappe wasserdicht verschließen. Kabelkanal auf- und zudeckeln wird gesondert vergütet. Ausbau von Kabelkanälen wird gesondert vergütet. Die Entsorgung / Verwertung wird gesondert vergütet.', 'm', 'Kabel, Leitungen und Zubehör'),
